from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; q.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                out.append((min(ys),max(ys),min(xs),max(xs),len(cells)))
    return out

def transform(g):
    g=[r[:] for r in g]; cs=comps(g)
    if len(cs)!=2: return g
    big=max(cs,key=lambda c:c[4]); small=min(cs,key=lambda c:c[4])
    r0,r1,c0,c1,_=small
    # extend right to big's right edge (and down if needed)
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if g[i][j]==0: g[i][j]=1
    rb0,rb1,cb0,cb1,_=big
    for i in range(r0,r1+1):
        for j in range(c1+1,cb1+1):
            g[i][j]=1
    for i in range(r1+1,rb1+1):
        for j in range(c0,cb1+1):
            g[i][j]=1
    return g

